import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        n = int(next(iterator))
        k = int(next(iterator))
        s = list(next(iterator))

        half_k = k // 2

        fixed = [-1] * k
        conflict = False

        for i in range(n):
            if s[i] != '?':
                pos = i % k
                val = 1 if s[i] == '1' else 0
                if fixed[pos] != -1 and fixed[pos] != val:
                    conflict = True
                    break
                fixed[pos] = val

        if conflict:
            results.append("NO")
            continue

        cnt0 = 0
        cnt1 = 0
        for x in fixed:
            if x == 0:
                cnt0 += 1
            elif x == 1:
                cnt1 += 1

        if cnt0 > half_k or cnt1 > half_k:
            results.append("NO")
            continue

        if k < n:
            first_win = -1
            last_win = -1

            for i in range(k):
                if fixed[i] == 0:
                    if first_win == -1:
                        first_win = i
                    last_win = i

            if first_win != -1 and last_win != -1:
                gap = last_win - first_win
                if gap >= k:
                    results.append("NO")
                    continue

            for i in range(k):
                if fixed[i] == -1:
                    fixed[i] = 0

            cnt0 = 0
            cnt1 = 0
            for x in fixed:
                if x == 0:
                    cnt0 += 1
                else:
                    cnt1 += 1

            if cnt0 > half_k or cnt1 > half_k:
                results.append("NO")
                continue

        results.append("YES")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
